import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './App.css';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import ContactForm from './components/ContactForm';

const App = () => {
  const [jobs, setJobs] = useState([]);
  const [search, setSearch] = useState('');
  const [filters, setFilters] = useState({
    country: '',
    city: '',
    experience: '',
    sector: '',
    tags: '',
    hideClosed: false
  });

  const fetchJobs = async () => {
    try {
      const response = await axios.get('http://localhost:5000/jobs', {
        params: { ...filters }
      });
      setJobs(response.data);
    } catch (error) {
      console.error('Error fetching jobs', error);
    }
  };

  useEffect(() => {
    fetchJobs();
  }, [filters]);

  const handleFilterChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFilters({
      ...filters,
      [name]: type === 'checkbox' ? checked : value
    });
  };

  const handleSearchChange = (e) => {
    setSearch(e.target.value);
  };

  return (
    <div>
      <Navbar />
      <Hero />

      <div className="job-grid">
        {/* Column 1: Filters */}
        <div className="filters-column">
          <h3>Filters</h3>

          <div className="filter-group">
            <label>Country</label>
            <input type="text" name="country" value={filters.country} onChange={handleFilterChange} />
          </div>

          <div className="filter-group">
            <label>City</label>
            <input type="text" name="city" value={filters.city} onChange={handleFilterChange} />
          </div>

          <div className="filter-group">
            <label>Experience</label>
            <select name="experience" value={filters.experience} onChange={handleFilterChange}>
              <option value="">All</option>
              <option value="entry">Entry</option>
              <option value="mid">Mid</option>
              <option value="senior">Senior</option>
            </select>
          </div>

          <div className="filter-group">
            <label>Sector</label>
            <input type="text" name="sector" value={filters.sector} onChange={handleFilterChange} />
          </div>

          <div className="filter-group">
            <label>Tags</label>
            <input type="text" name="tags" value={filters.tags} onChange={handleFilterChange} />
          </div>

          <div className="filter-group">
            <label>
              <input
                type="checkbox"
                name="hideClosed"
                checked={filters.hideClosed}
                onChange={handleFilterChange}
              />
              Hide closed jobs
            </label>
          </div>
        </div>

        {/* Columns 2-4: Job Listings */}
        <div className="job-listings-column">
          <input
            type="text"
            className="search-input"
            placeholder="Search by job title"
            value={search}
            onChange={handleSearchChange}
          />

          <div className="job-list">
            {jobs
              .filter((job) => job.title.toLowerCase().includes(search.toLowerCase()))
              .map((job) => (
                <div key={job.id} className="job-card">
                  <h3>{job.title}</h3>
                  <p>{job.company} - {job.location}</p>
                  <p>{job.description}</p>
                  <a href={job.link} target="_blank" rel="noopener noreferrer">View Job</a>
                  <button onClick={() => axios.delete(`http://localhost:5000/jobs/${job.id}`).then(fetchJobs)}>
                    Delete
                  </button>
                </div>
              ))}
          </div>
        </div>
      </div>

      <ContactForm />
    </div>
  );
};

export default App;
